-- 9. Read-only check. tablesPresent = 2 and FL shops = 573 on a fresh run.
SELECT
  (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'cabinet_dealz' AND table_name IN ('fabrication_shops', 'countertop_quote_fab_shops')) AS tablesPresent,
  (SELECT COUNT(*) FROM cabinet_dealz.fabrication_shops WHERE state = 'FL') AS shops,
  (SELECT COUNT(*) FROM cabinet_dealz.fabrication_shops WHERE state = 'FL' AND zip IS NOT NULL) AS shopsWithZip;
